package com.pablo.controlgastos;

import android.app.*;import android.content.*;import android.database.Cursor;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.os.Bundle;import android.provider.Settings;import android.view.*;import android.widget.*;import java.io.*;import java.text.*;import java.util.*;

public class MainActivity extends Activity{
 private ExpenseDb db;private int BG,CARD,TEXT,MUTED;private final DecimalFormat money=new DecimalFormat("#,##0.00");private static final int REQ_EXPORT=44,REQ_IMPORT=45;private Uri lastIncomingUri;private boolean exportPrivate=false;
 @Override public void onCreate(Bundle b){ThemePrefs.applyBaseTheme(this);super.onCreate(b);initPalette();db=new ExpenseDb(this);build();handleIncomingExcel(getIntent());}
 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);handleIncomingExcel(i);}
 private void handleIncomingExcel(Intent i){if(i==null)return;Uri u=null;if(Intent.ACTION_VIEW.equals(i.getAction()))u=i.getData();else if(Intent.ACTION_SEND.equals(i.getAction())){try{u=i.getParcelableExtra(Intent.EXTRA_STREAM);}catch(Exception ignored){}if(u==null&&i.getClipData()!=null&&i.getClipData().getItemCount()>0)u=i.getClipData().getItemAt(0).getUri();}if(u==null||u.equals(lastIncomingUri))return;lastIncomingUri=u;final Uri x=u;getWindow().getDecorView().postDelayed(()->previewImport(x),180);}
 private void initPalette(){boolean l=ThemePrefs.isLight(this);BG=l?Color.rgb(246,248,249):Color.rgb(11,18,24);CARD=l?Color.WHITE:Color.rgb(22,32,41);TEXT=l?Color.rgb(31,38,44):Color.rgb(242,245,247);MUTED=l?Color.rgb(95,105,112):Color.rgb(158,169,178);}
 private int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}private GradientDrawable bg(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;}private TextView tv(String s,int z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setPadding(dp(10),dp(8),dp(10),dp(8));return v;}private Button btn(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(TEXT);b.setBackground(bg(CARD,14));return b;}private void addButton(LinearLayout root,Button b){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(58));p.setMargins(0,dp(7),0,dp(7));root.addView(b,p);}
 private void build(){ScrollView sc=new ScrollView(this);sc.setBackgroundColor(BG);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(18),dp(18),dp(18),dp(30));root.setBackgroundColor(BG);root.setOnApplyWindowInsetsListener((v,i)->{root.setPadding(dp(18),i.getSystemWindowInsetTop()+dp(34),dp(18),i.getSystemWindowInsetBottom()+dp(30));return i;});root.requestApplyInsets();sc.addView(root);TextView t=tv("Ajustes",28,TEXT);t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);root.addView(t);root.addView(tv("Banco, importación, reglas, categorías, seguridad y herramientas",14,MUTED));TextView bank=tv("BANCO E IMPORTACIÓN",13,MUTED);bank.setTypeface(Typeface.DEFAULT,Typeface.BOLD);root.addView(bank);Button scan=btn("🔔 Leer notificaciones activas"),imp=btn("⬆ Importar archivo eBROU / respaldo (.xls)"),setup=btn("🔐 Configurar acceso a notificaciones"),notif=btn(notificationEnabled()?"🟢 Lectura de notificaciones: activa":"🔴 Abrir acceso a notificaciones");addButton(root,scan);addButton(root,imp);addButton(root,setup);addButton(root,notif);root.addView(tv("‘Leer notificaciones activas’ vuelve a procesar las notificaciones que todavía estén visibles en el celular. Es útil si una compra BROU no se agregó automáticamente.",13,MUTED));TextView rulesTitle=tv("CATEGORÍAS Y REGLAS",13,MUTED);rulesTitle.setTypeface(Typeface.DEFAULT,Typeface.BOLD);root.addView(rulesTitle);Button rules=btn("✅ Lista blanca: palabras y categorías"),black=btn("⛔ Lista negra: excluir notificaciones"),cats=btn("🎨 Categorías y colores"),rec=btn("↻ Movimientos recurrentes");addButton(root,rules);addButton(root,black);addButton(root,cats);addButton(root,rec);TextView dataTitle=tv("DATOS Y CONFIGURACIÓN",13,MUTED);dataTitle.setTypeface(Typeface.DEFAULT,Typeface.BOLD);root.addView(dataTitle);Button appearance=btn("⚙ Apariencia y seguridad"),recovery=btn("🗑 Papelera y deshacer"),exp=btn("⬇ Exportar respaldo completo Excel"),add=btn("＋ Agregar movimiento manual");addButton(root,appearance);addButton(root,recovery);addButton(root,exp);addButton(root,add);root.addView(tv("El Excel funciona como respaldo completo. Al exportar podés decidir si también querés incluir correo y tarjetas de crédito con sus estados y movimientos. Un Excel bancario común nunca modifica correo, tarjetas ni configuración.",13,MUTED));setContentView(sc);scan.setOnClickListener(v->scanActiveNotifications());imp.setOnClickListener(v->pickBankFile());rules.setOnClickListener(v->startActivity(new Intent(this,RulesActivity.class)));black.setOnClickListener(v->startActivity(new Intent(this,BlacklistActivity.class)));cats.setOnClickListener(v->startActivity(new Intent(this,CategorySettingsActivity.class)));setup.setOnClickListener(v->startActivity(new Intent(this,NotificationSetupActivity.class)));exp.setOnClickListener(v->exportExcel());rec.setOnClickListener(v->showRecurring());add.setOnClickListener(v->showAdd(false));notif.setOnClickListener(v->openNotificationSettings());appearance.setOnClickListener(v->showAppearanceSecurity());recovery.setOnClickListener(v->showRecovery());}
 private void showRecovery(){LinearLayout box=form();Button undo=btn("↶ Deshacer último cambio");box.addView(undo);TextView h=tv("PAPELERA",13,MUTED);h.setTypeface(Typeface.DEFAULT,Typeface.BOLD);box.addView(h);Cursor c=db.trashItems();boolean any=false;SimpleDateFormat df=new SimpleDateFormat("dd/MM/yyyy",Locale.US);while(c.moveToNext()){any=true;long trashId=c.getLong(0);String type=c.getString(2),cur=c.getString(4),cat=c.getString(5),desc=c.getString(6);double amount=c.getDouble(3);long ts=c.getLong(7);LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);row.setPadding(dp(8),dp(6),dp(8),dp(6));row.addView(tv((desc==null?"Sin descripción":desc)+" · "+cur+" "+money.format(amount),15,TEXT));row.addView(tv(df.format(new Date(ts))+" · "+type+" · "+(cat==null?"Sin categoría":cat),12,MUTED));Button restore=btn("Restaurar");row.addView(restore);box.addView(row);restore.setOnClickListener(v->{if(db.restoreTrash(trashId))Toast.makeText(this,"Movimiento restaurado",Toast.LENGTH_SHORT).show();else Toast.makeText(this,"No se pudo restaurar",Toast.LENGTH_LONG).show();});}c.close();if(!any)box.addView(tv("La papelera está vacía.",14,MUTED));Button empty=btn("Vaciar papelera");box.addView(empty);AlertDialog d=new AlertDialog.Builder(this).setTitle("Papelera y deshacer").setView(box).setNegativeButton("Cerrar",null).create();undo.setEnabled(db.canUndo());undo.setOnClickListener(v->{Toast.makeText(this,db.undoLastChange(),Toast.LENGTH_LONG).show();d.dismiss();});empty.setEnabled(any);empty.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Vaciar papelera").setMessage("Esta acción elimina definitivamente los elementos de la papelera.").setPositiveButton("Vaciar",(x,y)->{db.emptyTrash();d.dismiss();Toast.makeText(this,"Papelera vaciada",Toast.LENGTH_SHORT).show();}).setNegativeButton("Cancelar",null).show());d.show();}
 private void scanActiveNotifications(){if(!notificationEnabled()){new AlertDialog.Builder(this).setTitle("Acceso a notificaciones desactivado").setMessage("Primero habilitá el acceso a notificaciones para ControlGastos.").setPositiveButton("Abrir ajustes",(d,w)->openNotificationSettings()).setNegativeButton("Cancelar",null).show();return;}if(BankNotificationListener.scanNow())Toast.makeText(this,"Notificaciones activas procesadas. Revisá Inicio.",Toast.LENGTH_LONG).show();else{BankNotificationListener.requestListenerReconnect();Toast.makeText(this,"El lector no estaba conectado. Pedí la reconexión; probá nuevamente en unos segundos.",Toast.LENGTH_LONG).show();}}
 private SharedPreferences securityPrefs(){return getSharedPreferences("security",MODE_PRIVATE);}private void showAppearanceSecurity(){LinearLayout f=form();Switch light=new Switch(this);light.setText("Modo claro");light.setChecked(ThemePrefs.isLight(this));Switch bio=new Switch(this);bio.setText("Bloquear al abrir con huella/biometría");bio.setChecked(securityPrefs().getBoolean("biometric_lock",false));Switch shots=new Switch(this);shots.setText("Bloquear capturas y vista en recientes");shots.setChecked(securityPrefs().getBoolean("block_screenshots",false));Switch salary=new Switch(this);salary.setText("Pasar salario cobrado del 25 al 31 al día 1 del mes siguiente");salary.setChecked(ExpenseDb.salaryMonthShiftEnabled(this));f.addView(light);f.addView(bio);f.addView(shots);f.addView(salary);new AlertDialog.Builder(this).setTitle("Apariencia y seguridad").setView(f).setPositiveButton("Guardar",(d,w)->{boolean themeChanged=ThemePrefs.isLight(this)!=light.isChecked();ThemePrefs.setLight(this,light.isChecked());securityPrefs().edit().putBoolean("biometric_lock",bio.isChecked()).putBoolean("block_screenshots",shots.isChecked()).apply();ExpenseDb.setSalaryMonthShiftEnabled(this,salary.isChecked());db.reapplySalaryMonthRule();Toast.makeText(this,"Configuración guardada",Toast.LENGTH_SHORT).show();if(themeChanged)recreate();}).setNegativeButton("Cancelar",null).show();}
 private LinearLayout form(){LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);f.setPadding(dp(24),0,dp(24),0);return f;}private Spinner spinner(String[]v){Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,v));return s;}
 private double parseUserAmount(String raw)throws Exception{String s=raw==null?"":raw.trim().replace(" ","");if(s.isEmpty())throw new Exception();int comma=s.lastIndexOf(','),dot=s.lastIndexOf('.');if(comma>=0&&dot>=0){if(comma>dot)s=s.replace(".","").replace(',','.');else s=s.replace(",","");}else if(comma>=0)s=s.replace(',','.');else if(dot>=0&&s.length()-dot-1==3)s=s.replace(".","");double v=Double.parseDouble(s);if(v<=0)throw new Exception();return v;}
 private void showAdd(boolean recurring){LinearLayout f=form();Spinner type=spinner(new String[]{"GASTO","INGRESO"});EditText amount=new EditText(this);amount.setHint("Monto");amount.setInputType(2|8192);Spinner cur=spinner(new String[]{"UYU","USD"});EditText desc=new EditText(this);desc.setHint("Descripción");EditText cat=new EditText(this);cat.setHint("Categoría");f.addView(type);f.addView(amount);f.addView(cur);f.addView(desc);f.addView(cat);final Calendar chosen=Calendar.getInstance();Button date=btn("Fecha: "+new SimpleDateFormat("dd/MM/yyyy",Locale.US).format(chosen.getTime()));EditText day=null;if(recurring){day=new EditText(this);day.setHint("Día del mes (1-31)");day.setInputType(2);f.addView(day);}else{f.addView(date);date.setOnClickListener(v->new DatePickerDialog(this,(view,y,m,d)->{chosen.set(y,m,d);date.setText("Fecha: "+new SimpleDateFormat("dd/MM/yyyy",Locale.US).format(chosen.getTime()));},chosen.get(Calendar.YEAR),chosen.get(Calendar.MONTH),chosen.get(Calendar.DAY_OF_MONTH)).show());}final EditText dayF=day;new AlertDialog.Builder(this).setTitle(recurring?"Nuevo recurrente":"Nuevo movimiento").setView(f).setPositiveButton("Guardar",(d,w)->{try{double a=parseUserAmount(amount.getText().toString());String de=desc.getText().toString().trim();if(de.isEmpty())de="Sin descripción";String ca=cat.getText().toString().trim();if(ca.isEmpty())ca="Sin categoría";CategoryPrefs.register(this,ca);if(recurring){int recurringDay=Integer.parseInt(dayF.getText().toString());if(recurringDay<1||recurringDay>31)throw new Exception();db.addRecurring(type.getSelectedItem().toString(),a,cur.getSelectedItem().toString(),ca,de,recurringDay);}else db.addTx(type.getSelectedItem().toString(),a,cur.getSelectedItem().toString(),ca,de,"",chosen.getTimeInMillis(),"manual");Toast.makeText(this,"Guardado",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"Revisá los datos",Toast.LENGTH_LONG).show();}}).setNegativeButton("Cancelar",null).show();}
 private void showRecurring(){LinearLayout box=form();Cursor c=db.allRecurring();boolean any=false;while(c.moveToNext()){any=true;long id=c.getLong(0);String line=c.getString(1)+" · "+c.getString(3)+" "+money.format(c.getDouble(2))+" · día "+c.getInt(6)+" · "+c.getString(5);TextView v=tv(line,15,TEXT);box.addView(v);v.setOnLongClickListener(z->{new AlertDialog.Builder(this).setTitle("Eliminar recurrente").setMessage(line).setPositiveButton("Eliminar",(a,b)->db.deleteRecurring(id)).setNegativeButton("Cancelar",null).show();return true;});}c.close();if(!any)box.addView(tv("No hay movimientos recurrentes.",15,MUTED));Button add=btn("+ Agregar recurrente");box.addView(add);AlertDialog d=new AlertDialog.Builder(this).setTitle("Movimientos recurrentes").setView(box).setNegativeButton("Cerrar",null).create();add.setOnClickListener(v->{d.dismiss();showAdd(true);});d.show();}
 private void pickBankFile(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/vnd.ms-excel");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/vnd.ms-excel","application/octet-stream","*/*"});startActivityForResult(i,REQ_IMPORT);}
 private void exportExcel(){final boolean[] checked={false};new AlertDialog.Builder(this).setTitle("Exportar respaldo").setMultiChoiceItems(new String[]{"Incluir correo y tarjetas de crédito en el respaldo"},checked,(d,w,on)->checked[0]=on).setMessage("Si lo activás se guardarán también la dirección y configuración del correo, la credencial de aplicación codificada, las tarjetas, estados, movimientos y cuotas. Guardá ese archivo en un lugar privado.").setPositiveButton("Continuar",(d,w)->{exportPrivate=checked[0];Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/vnd.ms-excel");i.putExtra(Intent.EXTRA_TITLE,"ControlGastos_RESPALDO_"+new SimpleDateFormat("yyyyMMdd",Locale.US).format(new Date())+".xls");startActivityForResult(i,REQ_EXPORT);}).setNegativeButton("Cancelar",null).show();}
 @Override protected void onActivityResult(int r,int c,Intent data){super.onActivityResult(r,c,data);if(c!=RESULT_OK||data==null)return;if(r==REQ_EXPORT)writeExcel(data.getData());else if(r==REQ_IMPORT)previewImport(data.getData());}
 private void previewImport(Uri uri){final ProgressDialog p=ProgressDialog.show(this,"Leyendo Excel","Analizando movimientos y respaldo…",true,false);new Thread(()->{try{BankXlsImporter.Result result=BankXlsImporter.parse(this,uri);BackupXlsManager.Info backup=BackupXlsManager.inspect(this,uri);int existing=0,reconcilable=0;for(BankXlsImporter.Tx tx:result.rows){if(db.hasFingerprint(tx.fingerprint))existing++;else if(db.wouldLinkImportedToNotification(tx.type,tx.amount,tx.currency,tx.description,tx.ts))reconcilable++;}int ex=existing,rec=reconcilable,newCount=result.rows.size()-existing-reconcilable;runOnUiThread(()->{p.dismiss();String extra="";if(backup.isBackup){extra="\n\nRESPALDO COMPLETO DETECTADO\nCategorías: "+backup.categories+"\nRecurrentes: "+backup.recurring+"\nConfiguración: "+backup.prefEntries+" valores"+(backup.hasPrivateData?"\nCorreo y tarjetas: incluidos\nTarjetas: "+backup.cards+" · estados: "+backup.statements+" · movimientos: "+backup.cardMovements:"\nCorreo y tarjetas: no incluidos")+"\n\nSolo se restauran correo y tarjetas si el archivo los contiene; si no, los datos actuales se conservan.";}new AlertDialog.Builder(this).setTitle(backup.isBackup?"Restaurar respaldo ControlGastos":"Vista previa").setMessage("Movimientos detectados: "+result.rows.size()+"\nYa importados: "+ex+"\nPara conciliar con notificación: "+rec+"\nNuevos: "+newCount+extra).setPositiveButton(backup.isBackup?"Restaurar respaldo":"Importar y conciliar",(d,w)->commitImport(result,uri,backup.isBackup)).setNegativeButton("Cancelar",null).show();});}catch(Exception e){runOnUiThread(()->{p.dismiss();new AlertDialog.Builder(this).setTitle("No pude leer el Excel").setMessage(e.getMessage()).setPositiveButton("Aceptar",null).show();});}}).start();}
 private void commitImport(BankXlsImporter.Result r,Uri uri,boolean restoreBackup){BackupXlsManager.RestoreResult br=null;if(restoreBackup){try{br=BackupXlsManager.restore(this,uri,db);}catch(Exception e){new AlertDialog.Builder(this).setTitle("No se pudo restaurar").setMessage(e.getMessage()).setPositiveButton("Aceptar",null).show();return;}}int a=0,d=0;for(BankXlsImporter.Tx tx:r.rows){if(db.addImportedTx(tx.type,tx.amount,tx.currency,tx.category,tx.description,tx.original,tx.ts,"banco-xls",tx.fingerprint))a++;else d++;}String msg="Nuevos "+a+" · "+d+" existentes o conciliados";if(br!=null)msg+="\nRespaldo restaurado: "+br.categories+" categorías · "+br.recurring+" recurrentes · "+br.prefEntries+" ajustes"+(br.emailRestored?" · correo restaurado · "+br.cards+" tarjetas · "+br.cardMovements+" movimientos de tarjeta":"")+(br.movedToOther>0?" · "+br.movedToOther+" movimientos de categorías eliminadas pasaron a Otros":"");Toast.makeText(this,msg,Toast.LENGTH_LONG).show();if(restoreBackup)recreate();}
 private void writeExcel(Uri u){OutputStream os=null;jxl.write.WritableWorkbook wb=null;try{os=getContentResolver().openOutputStream(u);if(os==null)throw new IOException("No se pudo crear el archivo");wb=jxl.Workbook.createWorkbook(os);String[] headers={"Fecha","Descripción","Número de documento","Asunto","Dependencia","Débito","Crédito","Categoría"};jxl.write.DateFormat dfmt=new jxl.write.DateFormat("dd/MM/yyyy");jxl.write.WritableCellFormat dateFmt=new jxl.write.WritableCellFormat(dfmt);jxl.write.NumberFormat nfmt=new jxl.write.NumberFormat("#,##0.00");jxl.write.WritableCellFormat numFmt=new jxl.write.WritableCellFormat(nfmt);jxl.write.WritableSheet uyu=wb.createSheet("UYU",0),usd=wb.createSheet("USD",1);jxl.write.WritableSheet[] sheets={uyu,usd};for(jxl.write.WritableSheet sh:sheets){for(int c=0;c<headers.length;c++)sh.addCell(new jxl.write.Label(c,0,headers[c]));sh.setColumnView(0,14);sh.setColumnView(1,34);sh.setColumnView(2,36);sh.setColumnView(3,34);sh.setColumnView(4,20);sh.setColumnView(5,16);sh.setColumnView(6,16);sh.setColumnView(7,24);}int rUyu=1,rUsd=1,n=0;Cursor c=db.allTx();while(c.moveToNext()){String currency=c.getString(3)==null?"UYU":c.getString(3).toUpperCase(Locale.ROOT);jxl.write.WritableSheet sh="USD".equals(currency)?usd:uyu;int r="USD".equals(currency)?rUsd++:rUyu++;String type=c.getString(1),desc=c.getString(5),cat=c.getString(4),source=c.getString(8),original=c.getString(6),fingerprint=c.getString(9);sh.addCell(new jxl.write.DateTime(0,r,new Date(c.getLong(7)),dateFmt));sh.addCell(new jxl.write.Label(1,r,desc==null?"":desc));sh.addCell(new jxl.write.Label(2,r,(fingerprint==null||fingerprint.trim().isEmpty())?"":"CG:"+fingerprint.trim()));sh.addCell(new jxl.write.Label(3,r,original==null?"":original));sh.addCell(new jxl.write.Label(4,r,source==null?"ControlGastos":source));double amount=c.getDouble(2);if("INGRESO".equalsIgnoreCase(type))sh.addCell(new jxl.write.Number(6,r,amount,numFmt));else sh.addCell(new jxl.write.Number(5,r,amount,numFmt));sh.addCell(new jxl.write.Label(7,r,cat==null?"":cat));n++;}c.close();BackupXlsManager.appendBackup(this,wb,db,exportPrivate);wb.write();wb.close();wb=null;os.close();os=null;Toast.makeText(this,"Respaldo completo exportado: "+n+" movimientos"+(exportPrivate?" · correo y tarjetas incluidos":""),Toast.LENGTH_LONG).show();}catch(Exception e){try{if(wb!=null)wb.close();}catch(Exception ignored){}try{if(os!=null)os.close();}catch(Exception ignored){}Toast.makeText(this,"No se pudo exportar el respaldo",Toast.LENGTH_LONG).show();}}
 private boolean notificationEnabled(){String e=Settings.Secure.getString(getContentResolver(),"enabled_notification_listeners");return e!=null&&e.contains(getPackageName());}private void openNotificationSettings(){try{startActivity(new Intent("android.settings.ACTION_NOTIFICATION_LISTENER_SETTINGS"));}catch(Exception ignored){}}
}
